package io.github.jesterportfolio.hearth.combat;

import io.github.jesterportfolio.hearth.persistence.ServerProgressAccess;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.BooleanSupplier;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.combat.CombatContent.*;
import static io.github.jesterportfolio.hearth.combat.CombatAttempt.*;

final class CombatAttemptTest {
    static CombatContent content(Pool pool,int limit,LocationMode mode){return new CombatContent("trial","공개 전투",20,2,3000,new Revival(true,"rescue",pool,limit,0.5,mode,mode==LocationMode.FIXED?new FieldContent.Point(7,64,8):null,List.of(new Effect("RESISTANCE",0,40))));}
    static final class Actors implements Port {
        record Apply(UUID player,Pose position,double health,List<Effect> effects,BooleanSupplier current,CompletableFuture<Boolean> result) {}
        final List<Apply> applies=new ArrayList<>();final Map<UUID,UUID> cameras=new HashMap<>();boolean paused,safe=true,cameraFails;int freezes;
        public void freeze(boolean p){paused=p;freezes++;}public void camera(UUID p,UUID target){if(cameraFails)throw new IllegalStateException("CAMERA_FAILED");cameras.put(p,target);}
        public boolean safe(Pose p){return safe;}public CompletionStage<Boolean> revive(UUID p,Pose pos,double health,List<Effect> effects,BooleanSupplier current){var result=new CompletableFuture<Boolean>();applies.add(new Apply(p,pos,health,effects,current,result));return result;}
    }
    static final class Fixture {
        final UUID run=UUID.randomUUID(),world=UUID.randomUUID();final ServerProgressAccess access=new ServerProgressAccess();
        final ServerProgressAccess.Context p=access.forVerifiedServerLink(run,new UUID(1,1)),q=access.forVerifiedServerLink(run,new UUID(1,2)),r=access.forVerifiedServerLink(run,new UUID(1,3));
        final Object one=new Object(),two=new Object(),three=new Object();final AtomicLong clock=new AtomicLong(100);final Queue<Runnable> work=new ArrayDeque<>();final Actors port=new Actors();final Pose pose=new Pose(world,2.25,64,3.75,74,12);final CombatAttempt fight;
        Fixture(){this(content(Pool.SHARED,2,LocationMode.START),2);}Fixture(CombatContent content,int count){var roster=new ArrayList<Entrant>();roster.add(new Entrant(p,one,pose));if(count>=2)roster.add(new Entrant(q,two,pose));if(count>=3)roster.add(new Entrant(r,three,pose));fight=new CombatAttempt(run,world,1,content,roster,port,work::add,()->{},clock::get);}
        void pump(){while(!work.isEmpty())work.remove().run();}void deadP(){fight.died(p,one,pose);}Member member(UUID id){return fight.snapshot().members().stream().filter(m->m.player().equals(id)).findFirst().orElseThrow();}
    }
    @Test void rosterRemainsFixedRejectsWrongOwnerAndNewMidFightJoins(){var f=new Fixture();assertEquals(2,f.fight.snapshot().difficultyPlayers());f.fight.disconnect(f.q,f.two,f.pose);assertEquals(2,f.fight.snapshot().difficultyPlayers());assertThrows(IllegalStateException.class,()->f.fight.reconnect(f.r,new Object()));assertThrows(IllegalStateException.class,()->f.fight.view(f.access.forVerifiedServerLink(UUID.randomUUID(),f.p.playerId()),f.one));assertThrows(IllegalStateException.class,()->f.fight.died(f.p,new Object(),f.pose));assertThrows(IllegalArgumentException.class,()->new CombatAttempt(f.run,f.world,1,content(Pool.SHARED,2,LocationMode.START),List.of(new Entrant(f.p,f.one,f.pose),new Entrant(f.p,f.two,f.pose)),f.port,Runnable::run,()->{},f.clock::get));}
    @Test void allDeadWaitsWithoutAutomaticFailureOrNewAttempt(){var f=new Fixture();f.deadP();assertEquals(f.q.playerId(),f.port.cameras.get(f.p.playerId()));f.fight.died(f.q,f.two,f.pose);assertEquals(Phase.WIPE_WAIT,f.fight.snapshot().phase());assertEquals(Outcome.NONE,f.fight.snapshot().outcome());assertTrue(f.port.paused);assertNull(f.port.cameras.get(f.p.playerId()));assertTrue(f.fight.view(f.p,f.one).state().contains("전멸"));assertFalse(f.fight.playable(f.p,f.one));long revision=f.fight.snapshot().revision();f.fight.died(f.q,f.two,f.pose);assertEquals(revision,f.fight.snapshot().revision());}
    @Test void mixedOfflineAndReturnProtectionPauseOnlyFightTimeThenResume(){var f=new Fixture();f.deadP();var exact=new Pose(f.world,8.125,-24,9.25,89,-17);f.fight.disconnect(f.q,f.two,exact);assertEquals(Phase.PAUSED,f.fight.snapshot().phase());f.clock.addAndGet(2000);f.fight.poll();assertEquals(0,f.fight.snapshot().combatMillis());Object next=new Object();assertEquals(exact,f.fight.reconnect(f.q,next));assertFalse(f.fight.playable(f.q,next));f.fight.returned(f.q,next);assertEquals(Phase.PAUSED,f.fight.snapshot().phase());assertFalse(f.fight.playable(f.q,next));assertThrows(IllegalStateException.class,()->f.fight.died(f.q,next,exact));f.clock.addAndGet(3000);f.fight.poll();assertEquals(Phase.ACTIVE,f.fight.snapshot().phase());assertTrue(f.fight.playable(f.q,next));assertEquals(0,f.fight.snapshot().combatMillis());assertEquals(f.q.playerId(),f.port.cameras.get(f.p.playerId()));f.clock.addAndGet(100);f.fight.poll();assertEquals(100,f.fight.snapshot().combatMillis());assertEquals(2,f.fight.snapshot().difficultyPlayers());}
    @Test void allOfflineClosesAndOldSessionCannotReturn(){var f=new Fixture();f.fight.disconnect(f.p,f.one,f.pose);long revision=f.fight.snapshot().revision();f.fight.disconnect(f.p,f.one,f.pose);assertEquals(revision,f.fight.snapshot().revision());f.fight.disconnect(f.q,f.two,f.pose);assertEquals(Outcome.ALL_OFFLINE,f.fight.snapshot().outcome());assertEquals(Phase.CLOSED,f.fight.snapshot().phase());assertThrows(IllegalStateException.class,()->f.fight.reconnect(f.p,new Object()));assertTrue(f.port.paused);}
    @Test void deadReconnectRetainsSpectatorStateAndUsage(){var f=new Fixture();f.deadP();f.fight.disconnect(f.p,f.one,f.pose);assertThrows(IllegalStateException.class,()->f.fight.reconnect(f.p,f.one));Object next=new Object();f.fight.reconnect(f.p,next);assertTrue(f.member(f.p.playerId()).dead());assertNull(f.port.cameras.get(f.p.playerId()));f.fight.returned(f.p,next);assertTrue(f.member(f.p.playerId()).dead());assertEquals(f.q.playerId(),f.port.cameras.get(f.p.playerId()));assertFalse(f.fight.playable(f.p,next));assertThrows(IllegalStateException.class,()->f.fight.watchNext(f.p,f.one));}
    @Test void spectatorSwitchesOnlyBetweenNormalSurvivorsAndCameraFailureDoesNotRevive(){var f=new Fixture(content(Pool.SHARED,2,LocationMode.START),3);f.deadP();assertEquals(f.r.playerId(),f.fight.watchNext(f.p,f.one).orElseThrow());f.fight.disconnect(f.r,f.three,f.pose);assertEquals(f.q.playerId(),f.port.cameras.get(f.p.playerId()));f.port.cameraFails=true;assertThrows(IllegalStateException.class,()->f.fight.disconnect(f.q,f.two,f.pose));assertEquals(Phase.HOLD,f.fight.snapshot().phase());assertTrue(f.member(f.p.playerId()).dead());assertFalse(f.member(f.q.playerId()).dead());}
    @Test void sharedRevivalReservationAndRequestReplayPreventOverspending(){var f=new Fixture(content(Pool.SHARED,1,LocationMode.START),2);f.deadP();f.fight.died(f.q,f.two,f.pose);UUID request=UUID.randomUUID();var first=f.fight.revive(f.p,f.one,request,"rescue");assertSame(first,f.fight.revive(f.p,f.one,request,"rescue"));assertEquals(1,f.fight.snapshot().reserved());assertTrue(f.fight.revive(f.q,f.two,UUID.randomUUID(),"rescue").toCompletableFuture().isCompletedExceptionally());assertTrue(f.fight.revive(f.q,f.two,request,"rescue").toCompletableFuture().isCompletedExceptionally());var apply=f.port.applies.getFirst();assertTrue(apply.current().getAsBoolean());assertEquals(0.5,apply.health());assertEquals(f.pose,apply.position());apply.result().complete(true);f.pump();assertTrue(first.toCompletableFuture().isDone());assertFalse(first.toCompletableFuture().isCompletedExceptionally());assertEquals(1,f.fight.snapshot().sharedUsed());assertEquals(0,f.fight.snapshot().reserved());assertFalse(f.member(f.p.playerId()).dead());assertSame(first,f.fight.revive(f.p,f.one,request,"rescue"));assertEquals(1,f.port.applies.size());}
    @Test void personalRevivalBudgetIsNotConsumedByOtherParticipant(){var f=new Fixture(content(Pool.PERSONAL,1,LocationMode.START),2);f.deadP();f.fight.died(f.q,f.two,f.pose);var a=f.fight.revive(f.p,f.one,UUID.randomUUID(),"rescue");var b=f.fight.revive(f.q,f.two,UUID.randomUUID(),"rescue");assertEquals(2,f.fight.snapshot().reserved());f.port.applies.forEach(p->p.result().complete(true));f.pump();assertFalse(a.toCompletableFuture().isCompletedExceptionally());assertFalse(b.toCompletableFuture().isCompletedExceptionally());assertEquals(1,f.member(f.p.playerId()).used());assertEquals(1,f.member(f.q.playerId()).used());assertEquals(0,f.fight.snapshot().sharedUsed());f.deadP();assertTrue(f.fight.revive(f.p,f.one,UUID.randomUUID(),"rescue").toCompletableFuture().isCompletedExceptionally());}
    @Test void disabledWrongConditionOrUnsafePositionNeverApply(){for(boolean enabled:List.of(true,false)){var base=content(Pool.SHARED,2,LocationMode.START);var r=base.revival();var f=new Fixture(new CombatContent(base.id(),base.title(),20,2,3000,new Revival(enabled,r.condition(),r.pool(),r.limit(),r.healthFraction(),r.location(),r.fixed(),r.effects())),2);f.deadP();assertTrue(f.fight.revive(f.p,f.one,UUID.randomUUID(),"wrong").toCompletableFuture().isCompletedExceptionally());f.port.safe=false;assertTrue(f.fight.revive(f.p,f.one,UUID.randomUUID(),"rescue").toCompletableFuture().isCompletedExceptionally());assertTrue(f.port.applies.isEmpty());assertEquals(0,f.fight.snapshot().reserved());}}
    @Test void revivalLocationModesAreDistinctFromExactReconnectLocation(){for(var mode:LocationMode.values()){var f=new Fixture(content(Pool.SHARED,2,mode),2);var died=new Pose(f.world,20,72,30,91,3);f.fight.died(f.p,f.one,died);f.fight.revive(f.p,f.one,UUID.randomUUID(),"rescue");var position=f.port.applies.getFirst().position();assertEquals(mode==LocationMode.START?f.pose.x():mode==LocationMode.DEATH?died.x():7,position.x());assertEquals(f.world,position.world());}}
    @Test void failedOrStaleRevivalPreservesDeadStateAndReservationInHold(){for(boolean stale:List.of(false,true)){var f=new Fixture();f.deadP();var result=f.fight.revive(f.p,f.one,UUID.randomUUID(),"rescue");var apply=f.port.applies.getFirst();if(stale){f.fight.disconnect(f.p,f.one,f.pose);f.fight.reconnect(f.p,new Object());assertFalse(apply.current().getAsBoolean());apply.result().complete(true);}else apply.result().completeExceptionally(new IllegalStateException("APPLY_FAILED"));f.pump();assertTrue(result.toCompletableFuture().isCompletedExceptionally());assertEquals(Phase.HOLD,f.fight.snapshot().phase());assertTrue(f.member(f.p.playerId()).dead());assertEquals(0,f.fight.snapshot().sharedUsed());assertEquals(1,f.fight.snapshot().reserved());}}
    @Test void terminalResultWinsByProcessingOrderAndLateApplyCannotChangeIt(){var f=new Fixture();f.deadP();var pending=f.fight.revive(f.p,f.one,UUID.randomUUID(),"rescue");f.fight.victory();long revision=f.fight.snapshot().revision();assertTrue(pending.toCompletableFuture().isCompletedExceptionally());assertFalse(f.port.applies.getFirst().current().getAsBoolean());f.port.applies.getFirst().result().complete(true);f.pump();f.fight.failedCondition(true);assertEquals(revision,f.fight.snapshot().revision());assertEquals(Outcome.VICTORY,f.fight.snapshot().outcome());assertEquals(0,f.fight.snapshot().sharedUsed());assertTrue(f.port.cameras.values().stream().allMatch(Objects::isNull));var other=new Fixture();other.fight.failedCondition(false);assertEquals(Phase.ACTIVE,other.fight.snapshot().phase());other.fight.failedCondition(true);other.fight.victory();assertEquals(Outcome.REQUIRED_FAILURE,other.fight.snapshot().outcome());}
    @Test void invalidationHoldsOnlyThisAttemptAndStablePollingDoesNotChurnRevision(){var f=new Fixture();var other=new Fixture();f.fight.poll();long revision=f.fight.snapshot().revision();f.fight.poll();assertEquals(revision,f.fight.snapshot().revision());f.fight.invalidate();long held=f.fight.snapshot().revision();f.fight.invalidate();assertEquals(held,f.fight.snapshot().revision());assertEquals(Phase.HOLD,f.fight.snapshot().phase());assertTrue(other.fight.playable(other.p,other.one));}
    @Test void rejectedOwnerDeliveryNeverRunsWorldPortOnCompletionThread() throws Exception {var f=new Fixture();Thread owner=Thread.currentThread();var actors=new Actors();var fight=new CombatAttempt(f.run,f.world,1,content(Pool.SHARED,2,LocationMode.START),List.of(new Entrant(f.p,f.one,f.pose),new Entrant(f.q,f.two,f.pose)),actors,r->{throw new RejectedExecutionException();},()->{if(Thread.currentThread()!=owner)throw new AssertionError("Owner violation");},f.clock::get);fight.died(f.p,f.one,f.pose);var pending=fight.revive(f.p,f.one,UUID.randomUUID(),"rescue");int before=actors.freezes;var worker=new Thread(()->actors.applies.getFirst().result().complete(true));worker.start();worker.join();assertTrue(pending.toCompletableFuture().isCompletedExceptionally());assertEquals(before,actors.freezes);fight.poll();assertEquals(Phase.HOLD,fight.snapshot().phase());assertEquals("COMBAT_OWNER_DELIVERY_FAILED",fight.snapshot().error());}
    @Test void malformedContentAndEffectsAreRejectedBeforeStart(){assertThrows(IllegalArgumentException.class,()->new Effect("UNKNOWN",0,1));assertThrows(IllegalArgumentException.class,()->new Pose(UUID.randomUUID(),Double.NaN,1,1,0,0));assertThrows(IllegalArgumentException.class,()->new Revival(true,"rescue",Pool.SHARED,-1,0.5,LocationMode.START,null,List.of()));assertThrows(IllegalArgumentException.class,()->new Revival(true,"rescue",Pool.SHARED,1,0.5,LocationMode.FIXED,null,List.of()));assertThrows(IllegalArgumentException.class,()->CombatContent.parse(Map.of("format",9)));}
}
